import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { VisitLine } from "./VisitLine.js";

export class Visits {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "org.springframework.samples.petclinic.visits.model.Visits",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {number} petId
   * @returns {Promise<VisitLine[]>}
   */
  static async read(petId) {
    try {
      const returnObjectIC = await Visits.type
        .invokeStaticMethod("read", petId)
        .execute();

      await GraftUtils.RegisterType(VisitLine, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
